/** Per-chapter reading material for /book/chapters/[n], drawn from the
 * abridged edition (Agentic AI for Actuaries: A Concise Primer, SSSIA
 * 2026).
 *
 * This is the *excerpt tier* and it is deliberately bounded: each chapter
 * contributes its opening vignette and closing paragraph verbatim, plus a
 * condensed summary of the argument in between. The full abridged chapter
 * — roughly a thousand words each — is not in this repository and must not
 * be added to it; it is the gated download offered on /book/primer. */

export type ChapterContent = {
  /** The manuscript's sub-title line, where the chapter carries one. */
  subtitle?: string;
  /** Opening scene, verbatim. Every chapter of the book opens with one. */
  vignette: string;
  /** Condensed argument, 3 paragraphs. */
  summary: string[];
  /** Closing framing paragraph, verbatim. */
  closing: string;
  /** One sharp line for pull-quote and social preview. */
  pullQuote: string;
};

